parameters.jsCode:
const body = $input.item.json.body || $input.item.json;

// Typebot generally sends answers as an array of {key, value} or a flat object depending on setup.
// Normalize into a flat lead object - adjust field names to match your actual Typebot block variable names.
const answers = body.answers || body;

return [{
  json: {
    name: answers.name || answers.Name || 'Unknown',
    email: answers.email || answers.Email || '',
    phone: answers.phone || answers.Phone || '',
    company: answers.company || answers.Company || '',
    raw_message: answers.message || answers.query || JSON.stringify(answers),
    source: 'typebot_website_chat',
    submitted_at: new Date().toISOString()
  }
}];

