={
  "model": "qwen2.5:7b",
  "stream": false,
  "prompt": "You are a lead classifier for a digital agency called Nivy International (services: SEO, AI Automation, Virtual Assistant/VA services, Design, Video). Read the visitor's message and classify it.\n\nVisitor message: {{$json.raw_message.replace(/\"/g, '\\\"').slice(0,1000)}}\n\nReturn ONLY a valid JSON object with exactly these keys, no other text: service_type (one of: SEO, AI Automation, VA, Design, Video, Other), intent_summary (1 sentence, what the visitor actually wants), urgency (one of: immediate, exploring, just_browsing)."
}

parameters.jsCode:
const response = $input.item.json.response || '';
let parsed = {};
try {
  parsed = JSON.parse(response);
} catch (e) {
  const match = response.match(/\{[\s\S]*\}/);
  parsed = match ? JSON.parse(match[0]) : { service_type: 'Other', intent_summary: '', urgency: 'exploring' };
}

const lead = $('Normalize Typebot Payload').item.json;

return [{
  json: {
    ...lead,
    service_type: parsed.service_type || 'Other',
    intent_summary: parsed.intent_summary || '',
    urgency: parsed.urgency || 'exploring'
  }
}];
